  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "AR42, which shares the fluoro-amino-anilide and cinnamamide amide motif with the query, was detected in mouse brains after oral administration, directly demonstrating BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Compound 11, a cinnamyl/heteroaryl CNS penetrant, achieved a brain:plasma ratio of ~2.9 in rats after oral dosing, supporting meaningful CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tranilast, a cinnamamide with an ionizable carboxylic acid, had plasma:brain >100 after oral dosing; the acid is absent in the query, so this failure is weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Belinostat showed limited CSF penetration (<10% of free plasma exposure) in primates, but its hydroxamate/sulfonamide structure is less similar to the query and is offset by its own brain-activity evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a lipophilic cinnamamide/aniline amide without an ionizable acid, and the closest direct BBB evidence (AR42) plus multiple cinnamamide/heteroaryl CNS-penetrant analogues support meaningful brain access; limited CSF evidence from belinostat is less transferable and outweighed.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query; closest analogue similarity is moderate (0.46).",
    "Efflux-transporter status and unbound brain concentrations were not directly assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

